import { useState, useRef } from "react";
import axios from "axios";
import { motion, AnimatePresence } from "framer-motion";

export default function App() {
  const [code, setCode] = useState("");
  const [explanation, setExplanation] = useState("");
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const explanationRef = useRef(null);

  const explainCode = async () => {
    if (!code.trim()) {
      setExplanation("Please paste some code first.");
      return;
    }

    setLoading(true);
    setExplanation("");

    try {
      const res = await axios.post(
        "http://localhost:8000/explain",
        { code },
        {
          headers: { "Content-Type": "application/json" },
          timeout: 300000
        }
      );

      setExplanation(res.data.explanation || "No explanation returned.");
    } catch (err) {
      console.error(err);

      if (err.code === "ECONNABORTED") {
        setExplanation("Request timed out. Try smaller code.");
      } else {
        setExplanation(
          err.response?.data?.explanation ||
          "Backend not reachable. Check server."
        );
      }
    }

    setLoading(false);
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(explanation);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  /* ✅ Semantic Highlighting Only */
  const renderExplanation = (text) => {
    if (!text) return null;

    const keywords = [
      "def", "return", "if", "else", "elif",
      "for", "while", "import", "from",
      "with", "open", "class", "try",
      "except", "True", "False", "None"
    ];

    const pattern = new RegExp(
      `\\b(${keywords.join("|")})\\b|\\b\\w+\\(\\)|\\b[A-Za-z_][A-Za-z0-9_]*\\b`,
      "g"
    );

    return text.split(pattern).map((part, index) => {
      if (!part) return null;

      // Python keywords
      if (keywords.includes(part)) {
        return (
          <span key={index} className="text-purple-400 font-semibold">
            {part}
          </span>
        );
      }

      // Function calls
      if (part.endsWith("()")) {
        return (
          <span key={index} className="text-yellow-400 font-mono">
            {part}
          </span>
        );
      }

      // Variables (simple heuristic)
      if (/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(part) && part.length < 20) {
        return (
          <span key={index} className="text-blue-300 font-medium">
            {part}
          </span>
        );
      }

      return <span key={index}>{part}</span>;
    });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-900 to-blue-900 px-6 py-12">

      <div className="max-w-5xl mx-auto space-y-10">

        <div className="text-center space-y-4">
          <h1 className="text-5xl font-bold text-white">
            code explAIner
          </h1>
          <p className="text-slate-400">
            Explain small or large Python programs instantly.
          </p>
        </div>

        <div className="bg-slate-800 rounded-2xl p-6 border border-slate-700 shadow-xl space-y-4">
          <textarea
            className="w-full h-56 bg-transparent text-slate-100 font-mono text-sm outline-none resize-none"
            placeholder="Paste your code here..."
            value={code}
            onChange={(e) => setCode(e.target.value)}
          />

          <div className="flex justify-end">
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={explainCode}
              disabled={loading}
              className="px-6 py-3 rounded-xl bg-blue-600 hover:bg-blue-700 transition text-white font-semibold disabled:opacity-50"
            >
              {loading ? "Generating explanation..." : "Explain Code"}
            </motion.button>
          </div>
        </div>

        <AnimatePresence>
          {explanation && (
            <motion.div
              ref={explanationRef}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 0.3 }}
              className="bg-slate-800 rounded-2xl p-8 border border-slate-700 shadow-2xl max-h-[500px] overflow-y-auto"
            >
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-semibold text-white">
                  Explanation:
                </h3>

                <button
                  onClick={copyToClipboard}
                  className="text-xs px-3 py-1.5 rounded-lg bg-slate-700 hover:bg-slate-600 transition text-white"
                >
                  {copied ? "Copied!" : "Copy"}
                </button>
              </div>

              <div className="text-slate-300 whitespace-pre-wrap leading-7 text-[15px]">
                {renderExplanation(explanation)}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <footer className="text-center text-slate-500 text-sm pt-10">
          Built with React · FastAPI · Ollama · Mistral
        </footer>

      </div>
    </div>
  );
}
